import{_ as o,o as t,c as i,a5 as a}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"二、集成Swagger2","description":"","frontmatter":{"title":"二、集成Swagger2","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/后端快速开发/二、集成Swagger2.md","filePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/后端快速开发/二、集成Swagger2.md"}'),r={name:"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/后端快速开发/二、集成Swagger2.md"};function n(c,e,l,d,p,s){return t(),i("div",null,[...e[0]||(e[0]=[a(`<div><p>具体实现 添加<code>Maven</code>依赖</p><p>&lt;!--swagger2--&gt; &lt;dependency&gt; &lt;groupId&gt;io.springfox&lt;/groupId&gt; &lt;artifactId&gt;springfox-swagger2&lt;/artifactId&gt; &lt;version&gt;2.9.2&lt;/version&gt; &lt;/dependency&gt; &lt;dependency&gt; &lt;groupId&gt;io.springfox&lt;/groupId&gt; &lt;artifactId&gt;springfox-swagger-ui&lt;/artifactId&gt; &lt;version&gt;2.9.2&lt;/version&gt; &lt;/dependency&gt; 创建<code>Swagger</code>配置</p><p>package com.minchengjianshe.organizationalandpersonal.configuration; import io.swagger.annotations.ApiOperation; import springfox.documentation.service.Contact; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import springfox.documentation.builders.ApiInfoBuilder; import springfox.documentation.builders.PathSelectors; import springfox.documentation.builders.RequestHandlerSelectors; import springfox.documentation.service.ApiInfo; import springfox.documentation.spi.DocumentationType; import springfox.documentation.spring.web.plugins.Docket; import springfox.documentation.swagger2.annotations.EnableSwagger2; @Configuration @EnableSwagger2 public class SwaggerConfig { @Bean public Docket docket() { return new Docket(DocumentationType.SWAGGER_2) .select() // apis 指定生成<code>API</code>的扫描条件</p><pre><code>    .apis(RequestHandlerSelectors.withMethodAnnotation(ApiOperation.class))
    //
</code></pre><p>扫描包</p><pre><code>    // .apis(RequestHandlerSelectors.basePackage(&quot;com.zhuqc.framework.controller&quot;))
    // paths
</code></pre><p>指定生成<code>API</code>的</p><p>path .paths(PathSelectors.any()) .build() // 文档信息</p><pre><code>    .apiInfo(apiInfo());
</code></pre><p>} private ApiInfo apiInfo() { return new ApiInfoBuilder() .title(&quot; 从零搭建后端框架</p><ul><li>&quot;)</li><li>.description(&quot;API</li></ul><p>接口文档</p><p>&quot;) .termsOfServiceUrl(&quot;<a href="https://github.com/zhuqianchang/framework" target="_blank" rel="noreferrer">https://github.com/zhuqianchang/framework</a>&quot;) .contact(new Contact(&quot;zhuqianchang&quot;, &quot;&quot;, &quot;&quot;)) .version(&quot;0.0.1&quot;) .build(); } }</p><ul><li><code>@EnableSwagger2</code> 开启<code>Swagger2</code></li><li><code>apis</code> 用来指定扫描的条件</li><li><code>RequestHandlerSelectors.basePackage(&quot;com.zhuqc.framework.controller&quot;)</code>，扫描指定包</li><li><code>RequestHandlerSelectors.withClassAnnotation((Api.class)</code>，扫描<code>@Api</code>标注的类</li><li><code>RequestHandlerSelectors.withMethodAnnotation(ApiOperation.class)</code>，扫描<code>@ApiOperation</code>标注的方法</li><li><code>RequestHandlerSelectors.any()</code>，总是<code>true</code></li><li><code>RequestHandlerSelectors.none()</code>，总是<code>false</code></li><li>默认配置是没有<code>@ApiIgnore</code>标注的类和方法</li><li><code>paths</code> 用来指定生成<code>API</code>的<code>path</code></li><li><code>PathSelectors.any()</code>，总是<code>true</code></li><li><code>PathSelectors.none()</code>，总是<code>false</code></li><li><code>PathSelectors.regex()</code>，正则表达式匹配</li><li><code>PathSelectors.ant()</code>，<code>Ant</code>表达式匹配</li><li><code>apiInfo</code> 用来指定文档信息</li></ul><p><code>Swagger</code>使用 <code>@Api(description = &quot;Hello</code>服务</p><p>&quot;) @RestControllerpublic class HelloController { @ApiOperation(value = &quot; 打招呼<code>&quot;, notes = &quot;</code>打招呼详情描述</p><p>&quot;) @ApiImplicitParams({ @ApiImplicitParam(name = &quot;name&quot;, value = &quot; 用户名</p><p>&quot;, required = true) }) @GetMapping(&quot;/hello/{name}&quot;) public String hello(@PathVariableString name) { returnString.format(&quot;Hello %s!&quot;, name); } } 常见注解</p><ul><li><code>@Api</code> 修饰整个类，描述整个<code>Controller</code>的作用</li><li><code>@ApiOperation</code> 修饰方法，描述方法的作用</li><li><code>@ApiParam</code> 修饰参数，描述参数的作用</li><li><code>@ApiIgnore</code> 表示忽略当前<code>API</code></li><li><code>@ApiImplicitParams</code> 描述多个请求参数</li><li><code>@ApiImplicitParam</code> 描述一个请求参数</li><li><code>@ApiModel</code> 如果参数是对象，则在对象所在类上标注，用于描述对象</li><li><code>@ApiModelProperty</code> 如果参数是对象，则在对象所在类的属性上标注，用于描述对象的属性</li></ul><p>启动项目 准备工作已完成，启动项目后访问<code>Swagger</code>地址：<code>http://localhost:8080/swagger-ui.html</code></p></div>`,1)])])}const m=o(r,[["render",n]]);export{u as __pageData,m as default};
